def _sig(v):
    v = np.asarray(v, dtype=float)
    if v.ndim != 2 or v.shape[0] != 2:
        return -1.0
    w = np.cos(np.arange(v.size, dtype=float) + 1.0)
    flat = 1.0e2 * v.ravel()
    return float(v.shape[1] + np.sum(np.abs(flat)) + flat @ w)
